out<-"analysis/gamewell_sensitivity_2026-10-16";s<-read.csv(file.path(out,"SENSITIVITY_SUMMARY_CORRECTED.csv"),stringsAsFactors=FALSE,check.names=FALSE)
i<-match("7b_i_log1p_minutes",s$analysis_id);lo<-s$wider_CI_lower[i];hi<-s$wider_CI_upper[i];thr<-.8326;s$category[i]<-if(lo> -thr&&hi<thr)"a"else if((hi<0||lo>0)&&(lo< -thr||hi>thr))"b"else if((hi<0||lo>0)&&lo>=-thr&&hi<=thr)"c"else"d"
reqids<-c(paste0("7a_",c("30h","36h","72h","no_cutoff")),"7b_i_log1p_minutes","7b_ii_cap_99","7e_min5_intervals","7f_no_zero_valence","7g_random_slope","7h_CR2_primary_no_refit");r<-s[match(reqids,s$analysis_id),];rob<-nrow(r)==10L&&all(!is.na(r$category)&r$category=="a");robtext<-if(rob)"Robust under all required prespecified sensitivities."else"Sensitive to one or more required prespecified analytic choices or unavailable fits."
write.csv(s,file.path(out,"SENSITIVITY_SUMMARY_FINAL.csv"),row.names=FALSE)
report<-c("# GameWell prespecified sensitivity analyses — final corrected report","","## Gate","","All six SHA-256 checks passed for Plan v1, Addenda 1–4, and the interval dataset. The primary cohort gate reproduced 5,076 intervals, 371 participants, and 171 participants with exposure variation.","","## Corrections and execution accounting","","The first run incorrectly applied the primary cohort's 48-hour cap to the four 7a cohorts. Addendum 4 defines those cohorts from all linked intervals with both valence endpoints present and exposure non-missing, applying 30h, 36h, 72h, or no cutoff. The initial four 7a fits and initial REPORT.md / SENSITIVITY_FIT_RESULTS.csv are invalid for 7a. Four valid 7a fits were subsequently run, with results in SENSITIVITY_7A_CORRECTED.csv. This means four extra, invalid 7a fits were executed; no files were overwritten.","","The final 7b(i) entry is expressed per 1 SD of within-person log(1 + minutes), and category is assigned against its prespecified +/-0.8326 points-per-SD threshold. All other model estimates/intervals are in valence points per hour. The corrected summary table is SENSITIVITY_SUMMARY_FINAL.csv.","","## Summary","","All estimates are associations with recorded linked-console play; no causal interpretation is made.","","Analysis | Cohort | N intervals | N participants | Estimate | Wider CI | Category | Fit status / singular","---|---|---:|---:|---:|---|---|---")
for(j in seq_len(nrow(s))){a<-s[j,];es<-if(is.finite(a$estimate))sprintf("%.6f",a$estimate)else"not fitted";ci<-if(is.finite(a$wider_CI_lower))sprintf("[%.4f, %.4f]",a$wider_CI_lower,a$wider_CI_upper)else"not available";n<-if(is.finite(a$n_intervals))as.character(a$n_intervals)else"aggregate";np<-if(is.finite(a$n_participants))as.character(a$n_participants)else"aggregate";sg<-if(is.na(a$singular_fit))"n/a"else as.character(a$singular_fit);report<-c(report,sprintf("%s | %s | %s | %s | %s | %s | %s | %s; %s",a$analysis_id,a$cohort_definition,n,np,es,ci,ifelse(is.na(a$category),"none",a$category),a$fit_status,sg))}
report<-c(report,"","## Robustness","",robtext,"The Addendum 4 criterion requires category (a) for all four 7a cohorts, both 7b variants, 7e, 7f, 7g and 7h. 7b(i) uses the +/-0.8326 points-per-SD threshold.","","## Other prespecified outputs","","7c is descriptive and has no category. 7d fits platform subsets only when at least 100 participants have at least two eligible intervals; Xbox-only and Nintendo-only qualified, while both-linked is counts only (32 participants total; 25 with at least two intervals). 7i had 371 successful leave-one-participant-out fits and no errors; the estimate distribution was min 0.02364, 2.5th percentile 0.06449, median 0.07306, 97.5th percentile 0.08346, max 0.11641; zero leave-one-out categories differed from primary. See LOO_AGGREGATE.csv.","","## Fit errors, convergence and limitations","","No lmer fit errors occurred in the completed model analyses. The both-linked 7d subset was counts only because it did not reach the prespecified threshold. All successful random-intercept fits were singular. A negative-eigenvalue convergence warning was emitted during the random-slope fit; it is listed in RUN_NOTICES.csv. The initial runner also emitted locale startup and package method-registration notices and singular-fit warnings. It printed model summaries but no study data rows or participant identifiers.","","Limitations include the interval-level coverage assumption, Nintendo first-party-only telemetry, ceiling compression and heterogeneous residual spread documented for the primary model, frequent singular fits, and observational design. Exposure is recorded linked-console play rather than total gaming. No primary model or life-satisfaction model was refitted.","","## Execution record","","R ran with --vanilla, using saved scripts that passed parse checks before execution. No dependencies were installed. The first gate script failed parsing due a UTF-8 BOM and was not run; a second gate-script revision errored while reading a manifest and did not fit a model; the third gate passed. The sensitivity runner and corrected reporting scripts ran. No files were modified, overwritten or deleted.")
writeLines(report,file.path(out,"REPORT_FINAL.md"),useBytes=TRUE)
notices<-data.frame(stage=c("initial_gate_parse","gate_revision_2","sensitivity_runner","random_slope_fit","sensitivity_runner_console"),notice=c("Parse failed: UTF-8 BOM; script not run","Stopped reading manifest column due basename call; no model run","Locale warnings; clubSandwich S3 registration notice; singular-fit notices","Model warning: failed to converge with 1 negative eigenvalue (-11)","Printed model summaries/aggregate fit objects; no participant IDs or data rows"),stringsAsFactors=FALSE);write.csv(notices,file.path(out,"RUN_NOTICES.csv"),row.names=FALSE)
cat("Final corrected aggregate report saved. Robustness criterion:",if(rob)"robust"else"sensitive","\n")